css:
:where(.wtyg-map-child_harvesting){--bg:#17141a; --panel:#1f1b22; --panel2:#262129; --line:#3a3340; --ink:#ece6e8; --mute:#a99fa8; --faint:#7d7380;
  --rose:#c27a8c; --link:#d7a9bd;}
:where(.wtyg-map-child_harvesting) *{box-sizing:border-box}
:where(.wtyg-map-child_harvesting),:where(.wtyg-map-child_harvesting){margin:0;height:100%;background:var(--bg);color:var(--ink);font:14px/1.45 "IBM Plex Sans",system-ui,sans-serif}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="app"],#wtyg-noid-app){position:fixed;inset:0;display:flex}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side){width:360px;max-width:100%;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;z-index:500}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side) header{padding:16px 16px 10px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side) h1{font:600 22px/1.15 "IBM Plex Serif",Georgia,serif;margin:0 0 6px;letter-spacing:.2px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side) .lede{margin:0;color:var(--mute);font-size:13px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="scroll"],#wtyg-noid-scroll){overflow:auto;flex:1;padding:6px 16px 24px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="map"],#wtyg-noid-map){flex:1;background:#0f0d11}
:where(.wtyg-map-child_harvesting) h2{font:600 12px/1 "IBM Plex Sans",sans-serif;text-transform:uppercase;letter-spacing:.09em;color:var(--mute);margin:18px 0 8px}
:where(.wtyg-map-child_harvesting) .row{display:flex;align-items:flex-start;gap:9px;padding:6px 4px;border-radius:6px;cursor:pointer}
:where(.wtyg-map-child_harvesting) .row:hover{background:var(--panel2)}
:where(.wtyg-map-child_harvesting) .row input{margin:3px 0 0;accent-color:#9b6f86}
:where(.wtyg-map-child_harvesting) .sw{flex:0 0 12px;height:12px;border-radius:50%;margin-top:3px;border:1.5px solid rgba(0,0,0,.35)}
:where(.wtyg-map-child_harvesting) .sw.sq{border-radius:2px}
:where(.wtyg-map-child_harvesting) .sw.ln{height:3px;border:none;border-radius:2px;margin-top:8px}
:where(.wtyg-map-child_harvesting) .row .t{flex:1}
:where(.wtyg-map-child_harvesting) .row .n{color:var(--faint);font-variant-numeric:tabular-nums;font-size:12px;margin-top:1px}
:where(.wtyg-map-child_harvesting) .row small{display:block;color:var(--faint);font-size:12px}
:where(.wtyg-map-child_harvesting) .grp{display:flex;align-items:center;justify-content:space-between;margin-top:14px}
:where(.wtyg-map-child_harvesting) .grp button,:where(.wtyg-map-child_harvesting) .chips button,:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="more"],#wtyg-noid-more) button{background:none;border:1px solid var(--line);color:var(--mute);border-radius:999px;padding:3px 10px;font:12px "IBM Plex Sans",sans-serif;cursor:pointer}
:where(.wtyg-map-child_harvesting) .grp button:hover,:where(.wtyg-map-child_harvesting) .chips button:hover{color:var(--ink);border-color:#5a4f5f}
:where(.wtyg-map-child_harvesting) .chips{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 10px}
:where(.wtyg-map-child_harvesting) .chips button.on{background:#3a2d3a;color:var(--ink);border-color:#6d5168}
:where(.wtyg-map-child_harvesting) .years{display:flex;align-items:center;gap:8px;color:var(--mute);font-size:12px}
:where(.wtyg-map-child_harvesting) .years input[type=number]{width:72px;background:var(--panel2);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:4px 6px;font:13px "IBM Plex Sans",sans-serif}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="q"],#wtyg-noid-q){width:100%;background:var(--panel2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:14px "IBM Plex Sans",sans-serif}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="q"],#wtyg-noid-q)::placeholder{color:var(--faint)}
:where(.wtyg-map-child_harvesting) .note{color:var(--mute);font-size:12.5px}
:where(.wtyg-map-child_harvesting) .note p{margin:6px 0}
:where(.wtyg-map-child_harvesting) details{border-top:1px solid var(--line);padding:8px 0}
:where(.wtyg-map-child_harvesting) details summary{cursor:pointer;color:var(--ink);font-weight:500}
:where(.wtyg-map-child_harvesting) .wf{margin:8px 0 12px;padding-left:10px;border-left:2px solid #4b3f4e}
:where(.wtyg-map-child_harvesting) .wf b{display:block;font-weight:500}
:where(.wtyg-map-child_harvesting) .wf a{color:var(--link)}
:where(.wtyg-map-child_harvesting) .key{display:grid;grid-template-columns:16px 1fr;gap:6px 8px;align-items:center;font-size:12px;color:var(--mute);margin:6px 0}
:where(.wtyg-map-child_harvesting) .key i{width:12px;height:12px;border-radius:50%;display:block;justify-self:center}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:none}
:where(.wtyg-map-child_harvesting) h3.sub .fold{all:unset;cursor:pointer;display:flex;align-items:center;gap:6px;width:100%}
:where(.wtyg-map-child_harvesting) h3.sub .ar{color:var(--mute);width:12px}
:where(.wtyg-map-child_harvesting) h3.sub .hn{margin-left:auto;color:var(--faint);font-weight:400;font-size:12px}
:where(.wtyg-map-child_harvesting) h3.sub{font:600 13px/1.3 "IBM Plex Sans",sans-serif;color:#d9ccd3;margin:14px 0 4px;padding-top:8px;border-top:1px solid var(--line)}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="info"],#wtyg-noid-info){position:absolute;right:10px;top:52px;z-index:600;width:330px;max-width:calc(100% - 20px);background:rgba(31,27,34,.96);border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.45)}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="infotoggle"],#wtyg-noid-infotoggle){width:100%;text-align:left;background:none;border:0;color:var(--ink);font:500 13px "IBM Plex Sans",sans-serif;padding:10px 12px;cursor:pointer}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="infotoggle"],#wtyg-noid-infotoggle)::after{content:" +";color:var(--mute)}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="info"],#wtyg-noid-info).open :is([data-wtyg-id="infotoggle"],#wtyg-noid-infotoggle)::after{content:" \2212"}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="infobody"],#wtyg-noid-infobody){display:none;max-height:calc(100vh - 140px);overflow:auto;padding:0 12px 12px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="info"],#wtyg-noid-info).open :is([data-wtyg-id="infobody"],#wtyg-noid-infobody){display:block}
:where(.wtyg-map-child_harvesting) .vs{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:6px 0;font-size:12px}
:where(.wtyg-map-child_harvesting) .vs span{background:#2c2430;border-radius:6px;padding:5px 7px;color:#e3d3da}
:where(.wtyg-map-child_harvesting) .vs span+span{background:#232a33;color:#cdd6e2}
:where(.wtyg-map-child_harvesting) .ch-list ol{margin:6px 0 0;padding-left:20px;max-height:300px;overflow:auto}
:where(.wtyg-map-child_harvesting) .ch-list li{margin:3px 0}
:where(.wtyg-map-child_harvesting) .ch-list li span{display:block;color:var(--faint);font-size:11px}
:where(.wtyg-map-child_harvesting) .leaflet-popup-content-wrapper{background:#221d25;color:var(--ink);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.5)}
:where(.wtyg-map-child_harvesting) .leaflet-popup-tip{background:#221d25}
:where(.wtyg-map-child_harvesting) .leaflet-popup-content{margin:14px 16px;font:13.5px/1.5 "IBM Plex Sans",sans-serif;max-height:min(60vh,480px);overflow:auto}
:where(.wtyg-map-child_harvesting) .leaflet-container a.leaflet-popup-close-button{color:var(--mute)}
:where(.wtyg-map-child_harvesting) .ch-pop h3{font:600 15.5px/1.3 "IBM Plex Serif",Georgia,serif;margin:0 0 4px}
:where(.wtyg-map-child_harvesting) .ch-pop .meta{color:var(--mute);font-size:12px;margin-bottom:8px}
:where(.wtyg-map-child_harvesting) .ch-pop .tag{display:inline-block;border:1px solid #5a4b59;border-radius:999px;padding:0 7px;font-size:11px;color:#d9c8d2;margin-right:4px}
:where(.wtyg-map-child_harvesting) .ch-pop .tag.al{border-color:#8a6a4f;color:#d8c4b4}
:where(.wtyg-map-child_harvesting) .ch-pop p{margin:6px 0}
:where(.wtyg-map-child_harvesting) .ch-pop .fig{color:#e3d3da;background:#2c2430;border-radius:6px;padding:6px 8px;font-size:12.5px}
:where(.wtyg-map-child_harvesting) .ch-pop .where{font-size:12px;color:var(--faint)}
:where(.wtyg-map-child_harvesting) .ch-pop ul{margin:4px 0 0;padding-left:18px}
:where(.wtyg-map-child_harvesting) .ch-pop li{margin:2px 0}
:where(.wtyg-map-child_harvesting) .ch-pop a{color:var(--link)}
:where(.wtyg-map-child_harvesting) .ch-pop .src{font-size:12px;color:var(--mute);border-top:1px solid #3a3340;margin-top:8px;padding-top:6px}
:where(.wtyg-map-child_harvesting) .ch-pop .rec+.rec{border-top:1px solid #3a3340;margin-top:10px;padding-top:8px}
:where(.wtyg-map-child_harvesting) .leaflet-control-attribution{background:rgba(23,20,26,.75)!important;color:var(--faint)!important}
:where(.wtyg-map-child_harvesting) .leaflet-control-attribution a{color:var(--mute)!important}
:where(.wtyg-map-child_harvesting) .leaflet-bar a{background:#221d25;color:var(--ink);border-color:var(--line)}
:where(.wtyg-map-child_harvesting) .leaflet-bar a:hover{background:#2c2630}
:where(.wtyg-map-child_harvesting) .bm{position:absolute;right:10px;top:10px;z-index:600;display:flex;gap:4px;background:rgba(31,27,34,.9);border:1px solid var(--line);border-radius:999px;padding:3px}
:where(.wtyg-map-child_harvesting) .bm button{background:none;border:0;color:var(--mute);padding:4px 10px;border-radius:999px;font:12px "IBM Plex Sans",sans-serif;cursor:pointer}
:where(.wtyg-map-child_harvesting) .bm button.on{background:#3a2d3a;color:var(--ink)}
:where(.wtyg-map-child_harvesting) .relief{filter:grayscale(1) invert(1) brightness(.62) contrast(1.15)}
:where(.wtyg-map-child_harvesting) .sat{filter:grayscale(.55) brightness(.6) contrast(1.05)}
@media (max-width:760px){:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="app"],#wtyg-noid-app){flex-direction:column-reverse}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side){width:100%;height:46%;border-right:0;border-top:1px solid var(--line)}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side).min{height:58px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:block;position:absolute;right:12px;top:12px;background:none;border:1px solid var(--line);color:var(--mute);border-radius:999px;padding:3px 10px;font:12px "IBM Plex Sans",sans-serif}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="side"],#wtyg-noid-side) header{position:relative}
:where(.wtyg-map-child_harvesting) .bm{top:10px}
:where(.wtyg-map-child_harvesting) :is([data-wtyg-id="info"],#wtyg-noid-info){top:auto;bottom:10px;right:10px;width:calc(100% - 20px)}}
